import {createGame,start,tick,requestDirection,pause,resume,getBest,saveBest} from './engine.js';import {render} from './renderer.js';
const $=id=>document.getElementById(id),canvas=$('maze');let game=createGame(),storage,best=0,viewport;try{storage=localStorage;}catch{}best=getBest(storage);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function resize(){const w=window.innerWidth||570,h=window.innerHeight||630,dpr=Math.min(window.devicePixelRatio||1,2),touch=w<=700||matchMedia('(pointer: coarse)').matches;viewport={dpr,top:54,bottom:touch?96:0};canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}resize();window.addEventListener('resize',resize);
function update(){ $('score').textContent=game.score;$('best').textContent=best;$('lives').textContent=game.lives?'● '.repeat(game.lives).trim():'—';$('lives').setAttribute('aria-label',`${game.lives} lives remaining`);$('pause').disabled=['ready','won','over'].includes(game.status);$('pause').textContent=game.status==='paused'?'Resume':'Pause';$('overlay').hidden=['running','hit'].includes(game.status);$('state').hidden=game.status==='ready';$('restart').hidden=game.status!=='paused';if(game.status==='paused'){$('state').textContent='Paused';$('play').textContent='Resume';}else if(['won','over'].includes(game.status)){$('state').textContent=`${game.status==='won'?'You won!':'Game over'} · ${game.score}`;$('play').textContent='Play again';}}
function newGame(){game=start(createGame());update();canvas.focus({preventScroll:true});}
function togglePause(){game.status==='paused'?resume(game):pause(game);update();}
$('play').addEventListener('click',()=>{if(game.status==='paused'){resume(game);update();canvas.focus({preventScroll:true});}else newGame();});$('pause').addEventListener('click',togglePause);$('restart').addEventListener('click',newGame);
for(const button of document.querySelectorAll('[data-direction]')){const act=()=>{if(game.status==='ready')newGame();requestDirection(game,button.dataset.direction);};button.addEventListener('pointerdown',e=>{e.preventDefault();act();});button.addEventListener('click',e=>{if(e.detail===0)act();});}
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase(),dir={arrowup:'up',w:'up',arrowdown:'down',s:'down',arrowleft:'left',a:'left',arrowright:'right',d:'right'}[key];if(dir){e.preventDefault();if(game.status==='ready')newGame();requestDirection(game,dir);}if(key==='p'||key==='escape'){if(key==='escape'&&document.fullscreenElement)return;e.preventDefault();togglePause();}});
let touch;canvas.addEventListener('pointerdown',e=>{touch={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointerup',e=>{if(!touch)return;const dx=e.clientX-touch.x,dy=e.clientY-touch.y;touch=null;if(Math.max(Math.abs(dx),Math.abs(dy))<12)return;requestDirection(game,Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up');});canvas.addEventListener('pointercancel',()=>touch=null);
document.addEventListener('visibilitychange',()=>{if(document.hidden){pause(game);update();}});window.addEventListener('blur',()=>{pause(game);update();});
if(!document.documentElement.requestFullscreen){$('fullscreen').hidden=true;}else{$('fullscreen').addEventListener('click',async()=>{try{document.fullscreenElement?await document.exitFullscreen():await document.documentElement.requestFullscreen();}catch{$('announcement').textContent='Fullscreen is not available here.'}});document.addEventListener('fullscreenchange',()=>{$('fullscreen').setAttribute('aria-label',document.fullscreenElement?'Exit fullscreen':'Enter fullscreen');resize();});}
if(!canvas.getContext('2d')){$('state').hidden=false;$('state').textContent='This browser cannot display the game.';$('play').disabled=true;}else{update();let last;function frame(now){const elapsed=last===undefined?0:Math.min(.1,(now-last)/1000);last=now;const status=game.status;tick(game,elapsed);if(game.score>best)best=saveBest(storage,game.score);if(status!==game.status&&['over','won'].includes(game.status)){$('announcement').textContent=`${game.status==='won'?'Maze cleared':'Game over'}. Score ${game.score}.`;$('play').focus({preventScroll:true});}if(game.events.includes('hit'))$('announcement').textContent=`Ghost got you. ${game.lives} lives left.`;render(canvas,game,reduced,viewport);update();requestAnimationFrame(frame);}requestAnimationFrame(frame);}
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_pacman_state',description:'Read the current maze game score, lives and status.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:async()=>({content:[{type:'text',text:JSON.stringify({status:game.status,score:game.score,lives:game.lives,dotsLeft:game.dots.size,best})}]})});}catch{}}
